    "html": "<div class=\"standard-code-block\" data-lang=\"json\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">JSON</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-json\"><span class=\"code-key\">&quot;noise_category_level&quot;</span>: &quot;parent&quot;</code></pre>\n</div>\n<p class=\"standard-p\">Supported values:</p>\n<div class=\"standard-code-block\" data-lang=\"text\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">TEXT</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-text\">parent\n\ntop</code></pre>\n</div>\n<p class=\"standard-p\">Suppose the noise structure is:</p>\n<div class=\"standard-code-block\" data-lang=\"tree\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">TREE</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-tree\">noise/\n\n<span class=\"code-tree\">└──</span> military/\n\n    <span class=\"code-tree\">└──</span> gunfire/\n\n        <span class=\"code-tree\">└──</span> <span class=\"code-wav\">recording.wav</span></code></pre>\n</div>\n<p class=\"standard-p\">With:</p>\n<div class=\"standard-code-block\" data-lang=\"json\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">JSON</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-json\"><span class=\"code-key\">&quot;noise_category_level&quot;</span>: &quot;parent&quot;</code></pre>\n</div>\n<p class=\"standard-p\">the category is:</p>\n<div class=\"standard-code-block\" data-lang=\"text\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">TEXT</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-text\">gunfire</code></pre>\n</div>\n<p class=\"standard-p\">With:</p>\n<div class=\"standard-code-block\" data-lang=\"json\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">JSON</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-json\"><span class=\"code-key\">&quot;noise_category_level&quot;</span>: &quot;top&quot;</code></pre>\n</div>\n<p class=\"standard-p\">the category is:</p>\n<div class=\"standard-code-block\" data-lang=\"text\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">TEXT</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-text\">military</code></pre>\n</div>\n<hr class=\"section-divider\" />",
