    "html": "<div class=\"standard-code-block\" data-lang=\"json\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">JSON</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-json\"><span class=\"code-key\">&quot;snr_db&quot;</span>: {\n\n    <span class=\"code-key\">&quot;type&quot;</span>: &quot;uniform&quot;,\n\n    <span class=\"code-key\">&quot;min&quot;</span>: <span class=\"code-num\">5.0</span>,\n\n    <span class=\"code-key\">&quot;max&quot;</span>: <span class=\"code-num\">20.0</span>\n\n}</code></pre>\n</div>\n<p class=\"standard-p\">Supported distributions:</p>\n<div class=\"standard-code-block\" data-lang=\"text\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">TEXT</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-text\">fixed\n\nchoice\n\nuniform</code></pre>\n</div>\n<p class=\"standard-p\">Fixed:</p>\n<div class=\"standard-code-block\" data-lang=\"json\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">JSON</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-json\">{\n\n    <span class=\"code-key\">&quot;type&quot;</span>: &quot;fixed&quot;,\n\n    <span class=\"code-key\">&quot;value&quot;</span>: <span class=\"code-num\">10</span>\n\n}</code></pre>\n</div>\n<p class=\"standard-p\">Choice:</p>\n<div class=\"standard-code-block\" data-lang=\"json\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">JSON</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-json\">{\n\n    <span class=\"code-key\">&quot;type&quot;</span>: &quot;choice&quot;,\n\n    <span class=\"code-key\">&quot;values&quot;</span>: [0, 5, 10, 15, 20]\n\n}</code></pre>\n</div>\n<p class=\"standard-p\">Uniform:</p>\n<div class=\"standard-code-block\" data-lang=\"json\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">JSON</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-json\">{\n\n    <span class=\"code-key\">&quot;type&quot;</span>: &quot;uniform&quot;,\n\n    <span class=\"code-key\">&quot;min&quot;</span>: <span class=\"code-num\">5</span>,\n\n    <span class=\"code-key\">&quot;max&quot;</span>: <span class=\"code-num\">20</span>\n\n}</code></pre>\n</div>\n<p class=\"standard-p\">The selected target value is stored in:</p>\n<div class=\"standard-code-block\" data-lang=\"text\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">TEXT</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-text\">target_snr_db</code></pre>\n</div>\n<p class=\"standard-p\">The actual SNR measured after encoding and decoding is stored in:</p>\n<div class=\"standard-code-block\" data-lang=\"text\">\n  <div class=\"code-block-header\">\n    <span class=\"code-lang-label\">TEXT</span>\n    <button class=\"code-copy-button\" onclick=\"copyCode(this)\" title=\"Copy to clipboard\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre><code class=\"language-text\">measured_snr_db</code></pre>\n</div>\n<hr class=\"section-divider\" />",
